    if (targets.length) {
      gsap.set(targets, { perspective: 2000 });

      gsap.fromTo(targets, 
        { opacity: 0, y: 30 }, 
        {
          opacity: 1,
          y: 0,
          duration: 0.6,
          delay: 0.5,
          ease: "power2.out",
          stagger: {
            each: 0.2,
            from: "start"
          }
        }
      );
    }
  });
</script>



